   [12]={next_id=13, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="瑟勒阿姨慷慨地允许我继续使用她的名字活下去，但我认为自己并不应该完全地取代她。", msg_color="", msg_size=0, talker="克里安卡", audio="", img="arts/ui/bg/story/storybg_10_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4519", 0, 0, 9.5, 211.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
